{"command":"python3 - <<'EOF'
import zipfile, re
p='/Users/yin/Documents/ybs/code/agent-work-u07-web-idea-acceptance/.agent-work/u07-acceptance/runtime/chat-sources/ws_01M21SVJVR9PGEA7E5DQR2XC0X/wi_01M2293P91XY36SRV9MAX6C750/src_01M2293PA51E6ZYJNC6RACFZWR/content.pptx'
z=zipfile.ZipFile(p)
names=sorted(z.namelist())
def txt(name):
    x=z.read(name).decode('utf-8')
    return ' | '.join(re.findall(r'<a:t>([^<]*)</a:t>', x))
for n in names:
    if re.match(r'ppt/slides/slide\d+\.xml$', n) or re.match(r'ppt/notesSlides/notesSlide\d+\.xml$', n):
        print(f'== {n} ==\n{txt(n)}\n')
EOF","description":"Extract pptx slide and notes text"}
